<script setup lang="ts">import { Head,useForm } from '@inertiajs/vue3';import { computed } from 'vue';import { Button } from '@/components/ui/button';import { Input } from '@/components/ui/input';const props=defineProps<{accounts:any[];totalCash:number;session:any|null;recentSessions:any[];transfers:any[];authorizations:any[];threshold:number;now:string;canOpen:boolean;canClose:boolean;canOperate:boolean;canRequestAuthorization:boolean}>();const petty=props.accounts.find(a=>a.code==='1105-CAJA-MENOR')?.id??props.accounts[0]?.id??'';const main=props.accounts.find(a=>a.code==='1105-CAJA')?.id??'';const open=useForm({financial_account_id:petty,opening_amount:0,source_account_id:main});const close=useForm({counted_amount:props.session?.expected??0,difference_reason:'',authorization_request_id:props.authorizations[0]?.id??''});const transfer=useForm({from_account_id:main,to_account_id:petty,amount:0,transferred_at:props.now,reason:''});const auth=useForm({reason:''});const difference=computed(()=>Number(close.counted_amount||0)-Number(props.session?.expected||0));const money=(v:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v||0);</script>
<template><Head title="Caja"/><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">Caja principal y caja menor</h1><p class="text-sm text-muted-foreground">El total consolida cuentas; los traslados internos no son ingresos ni gastos.</p></header><section class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="account in accounts" :key="account.id" class="rounded-xl border bg-card p-4"><p class="text-xs text-muted-foreground">{{account.name}}</p><strong class="text-xl">{{money(account.balance)}}</strong></div><div class="rounded-xl border border-amber-300 bg-amber-50 p-4 dark:bg-amber-950/30"><p class="text-xs text-muted-foreground">Efectivo total</p><strong class="text-xl">{{money(totalCash)}}</strong></div></section><div class="grid gap-5 lg:grid-cols-2"><section v-if="session" class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Sesión abierta · {{session.account}}</h2><p class="text-sm text-muted-foreground">{{session.opened_at}} · {{session.opener}}</p><div class="mt-4 grid grid-cols-2 gap-3"><div><small>Base inicial</small><p class="font-semibold">{{money(session.opening_amount)}}</p></div><div><small>Saldo esperado</small><p class="font-semibold">{{money(session.expected)}}</p></div></div><form v-if="canClose" class="mt-5 grid gap-3" @submit.prevent="close.post(`/cash/sessions/${session.id}/close`)"><Input v-model.number="close.counted_amount" type="number" min="0" placeholder="Efectivo contado"/><p class="text-sm">Diferencia: <strong :class="difference?'text-destructive':''">{{money(difference)}}</strong></p><Input v-model="close.difference_reason" :required="difference!==0" placeholder="Explicación si hay diferencia"/><select v-if="authorizations.length" v-model="close.authorization_request_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Sin autorización</option><option v-for="item in authorizations" :key="item.id" :value="item.id">{{item.reason}}</option></select><Button type="submit" :disabled="close.processing||Math.abs(difference)>threshold&&!close.authorization_request_id">Cerrar caja</Button></form><form v-if="canRequestAuthorization&&Math.abs(difference)>threshold&&!authorizations.length" class="mt-3 flex gap-2" @submit.prevent="auth.post(`/cash/sessions/${session.id}/difference-authorization`)"><Input v-model="auth.reason" required placeholder="Motivo de la diferencia"/><Button type="submit" variant="outline">Solicitar autorización</Button></form></section><section v-else-if="canOpen" class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Abrir caja menor</h2><form class="mt-4 grid gap-3" @submit.prevent="open.post('/cash/sessions')"><select v-model="open.financial_account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="a in accounts.filter(a=>a.accepts_payments)" :key="a.id" :value="a.id">{{a.name}}</option></select><Input v-model.number="open.opening_amount" type="number" min="0" placeholder="Base inicial"/><select v-model="open.source_account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Base ya existente en caja</option><option v-for="a in accounts.filter(a=>a.id!==open.financial_account_id)" :key="a.id" :value="a.id">Desde {{a.name}}</option></select><Button type="submit" :disabled="open.processing">Abrir caja</Button></form></section><section v-if="canOperate" class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Trasladar entre cajas</h2><form class="mt-4 grid gap-3" @submit.prevent="transfer.post('/cash/transfers',{onSuccess:()=>transfer.reset('amount','reason')})"><div class="grid grid-cols-2 gap-3"><select v-model="transfer.from_account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="a in accounts" :key="a.id" :value="a.id">Desde {{a.name}}</option></select><select v-model="transfer.to_account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="a in accounts" :key="a.id" :value="a.id">Hacia {{a.name}}</option></select></div><Input v-model.number="transfer.amount" type="number" min="1" placeholder="Valor"/><Input v-model="transfer.transferred_at" type="datetime-local"/><Input v-model="transfer.reason" required placeholder="Motivo"/><Button type="submit" variant="outline">Registrar traslado</Button></form></section></div><div class="grid gap-5 lg:grid-cols-2"><section class="rounded-xl border bg-card p-4"><h2 class="font-semibold">Cierres recientes</h2><div class="mt-2 divide-y"><p v-for="item in recentSessions" :key="item.id" class="flex justify-between py-2 text-sm"><span>{{item.account}} · {{item.closed_at}}</span><span>{{money(item.counted_closing_amount)}} <small :class="item.difference_amount?'text-destructive':''">({{money(item.difference_amount)}})</small></span></p></div></section><section class="rounded-xl border bg-card p-4"><h2 class="font-semibold">Traslados recientes</h2><div class="mt-2 divide-y"><p v-for="item in transfers" :key="item.id" class="flex justify-between py-2 text-sm"><span>{{item.document_number}} · {{item.from}} → {{item.to}}</span><span>{{money(item.amount)}}</span></p></div></section></div></main></template>
